section:
Magical Abilities


  Magic abilities involve the use of the characters magic pool and
  are only available to certain archetypes.


{% for ag in ability_groups
     if ag.get_family_id() == db.ABILITY_FAMILY_MAGIC_ID %}


  {{ ag.get_name() }}

  {{ ag.get_description() }}

  {% if ag.has_abilities() %}


    {{ ag.get_name() }}
    figure:{{ ag.get_id() }}_skill_tree

  {% endif %}

  {% for ability in ag.get_abilities()%}
  {{ build_ability(ability) }}
  {% endfor %}

{% endfor %}
